@@ -156,6 +156,11 @@ function evalMember(node: Extract<SimpleNode, { kind: 'member' }>, env: Env): un

 	const value = isParameterRead(node) ? readParameter(object, node.key, env) : object[node.key];

+	// `.item` with no item behind it is the engine's to report, as above.
+	if (node.object.kind === 'nodeRef' && (value === undefined || value === null)) {
+		throw new EngineFallbackError();
+	}
+
 	// Neither crosses an engine boundary the same way twice (the vm bridge
 	// drops a nested function but fails on an inherited one; legacy throws),
 	// so the configured engine decides rather than this module guessing.
@@ -508,6 +513,9 @@ function evalNodeRefCall(proxy: unknown, method: string, env: Env): unknown {
 	if (typeof fn !== 'function') throw new EngineFallbackError();

 	const result = bounded(fn.call(proxy));
+	// No item to read (`first()` on an empty node): the engine owns the
+	// error for whatever reads it next, so its message is the one reported.
+	if (result === undefined || result === null) throw new EngineFallbackError();
 	env.charge(isArray(result) ? result.length : 1);

 	return result;
